import jdk.jfr.consumer.*;import java.nio.file.*;import java.util.*;
public class LoadingJfrSummary {
 static Map<String,Long> cpu=new HashMap<>(),alloc=new HashMap<>(),wait=new HashMap<>(),anc=new HashMap<>(),totals=new HashMap<>();
 static void add(Map<String,Long> m,String k,long n){m.merge(k,n,Long::sum);}
 static void print(String title,Map<String,Long> m){System.out.println(title);m.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(22).forEach(System.out::println);}
 public static void main(String[] a)throws Exception {long gc=0,gcm=0,gcn=0,weight=0;try(var f=new RecordingFile(Path.of(a[0]))){while(f.hasMoreEvents()){var e=f.readEvent();if(a.length>1&&e.getStartTime().isBefore(java.time.Instant.parse(a[1])))continue;if(a.length>2&&!e.getStartTime().isBefore(java.time.Instant.parse(a[2])))continue;String t=e.getEventType().getName();if(t.equals("jdk.GCPhasePause")){gc+=e.getDuration().toNanos();gcm=Math.max(gcm,e.getDuration().toNanos());gcn++;}if(!Set.of("jdk.ExecutionSample","jdk.ObjectAllocationSample","jdk.ThreadPark","jdk.JavaMonitorEnter").contains(t))continue;var th=e.getThread(t.equals("jdk.ExecutionSample")||t.equals("jdk.NativeMethodSample")?"sampledThread":"eventThread");if(th==null)continue;String thread=th.getJavaName();if(thread.startsWith("Worker-Main"))thread="Worker-Main";var st=e.getStackTrace();if(st==null)continue;var s=st.getFrames().stream().map(x->x.getMethod().getType().getName()+"."+x.getMethod().getName()).toList();String b=s.stream().filter(x->x.startsWith("blockbranch.")).findFirst().orElse(s.getFirst());if(t.equals("jdk.ObjectAllocationSample")){long w=e.getLong("weight");weight+=w;add(alloc,thread+" "+e.getClass("objectClass").getName()+" @ "+b,w);}else if(t.equals("jdk.ThreadPark")||t.equals("jdk.JavaMonitorEnter")){if(thread.equals("Server thread"))add(wait,s.stream().filter(v->v.startsWith("blockbranch.")||v.contains("waitUntilNextTick")||v.contains("getChunk")||v.contains("waitForTasks")).findFirst().orElse(b),e.getDuration().toNanos()/1000000);}else {add(totals,thread,1);add(cpu,thread+" @ "+b,1);if(thread.equals("Server thread")||thread.equals("Worker-Main")||thread.equals("Render thread")||thread.equals("main"))for(String v:new HashSet<>(s))if(v.startsWith("blockbranch."))add(anc,thread+" "+v,1);}}}print("Execution sample totals by thread",totals);print("Execution sample leaves",cpu);print("Ancestor samples (overlap)",anc);for(String thread:List.of("Server thread","main","Render thread","Worker-Main"))for(String method:List.of("blockbranch.cubic.VerticalRuntime.activate","blockbranch.cubic.TerrainProfile$ProceduralSection.getStates","blockbranch.cubic.TerrainProfile.generate","blockbranch.client.cubic.ProceduralSectionCopies$Cache.copyBase"))System.out.println("TARGET "+thread+" "+method+"="+anc.getOrDefault(thread+" "+method,0L));print("Weighted allocated bytes",alloc);print("Server waits ms",wait);System.out.println("GC pauses="+gcn+" totalMs="+gc/1e6+" maxMs="+gcm/1e6+" allocationSampleWeight="+weight);}
}
